const SIZES = { small: { code: "s" }, large: { code: "l" }, custom: {} };
/** Sizes by their one-letter code; a size without a code has no entry. */
export const BY_CODE = Object.fromEntries(
  Object.entries(SIZES).flatMap(([name, size]) => ("code" in size ? [[size.code, name]] : [])),
);
export function nameOf(code) {
  return BY_CODE[code] ?? "unknown";
}
